{
    "id": "f73e9d7a-514f-48f3-a995-4f784c7e591b",
    "name": "Invoice Processing Workflow",
    "nodes": [
        {
            "id": "node-1",
            "workflowId": "f73e9d7a-514f-48f3-a995-4f784c7e591b",
            "actionId": "action-upload",
            "positionX": 50,
            "positionY": 150,
            "config": {
                "stepName": "Upload Invoice",
                "allowedFileTypes": ["pdf"],
                "bulkUpload": false
            },
            "action": {
                "id": "action-upload",
                "name": "Invoice Upload",
                "description": "Upload and process invoice documents"
            }
        },
        {
            "id": "node-2",
            "workflowId": "f73e9d7a-514f-48f3-a995-4f784c7e591b",
            "actionId": "action-validate",
            "positionX": 200,
            "positionY": 150,
            "config": {
                "stepName": "Validate Invoice Data",
                "validationRules": "{\"required\": [\"amount\", \"vendor\"]}"
            },
            "action": {
                "id": "action-validate",
                "name": "Data Validation",
                "description": "Validate data against defined rules"
            }
        },
        {
            "id": "node-3",
            "workflowId": "f73e9d7a-514f-48f3-a995-4f784c7e591b",
            "actionId": "action-api",
            "positionX": 350,
            "positionY": 150,
            "config": {
                "stepName": "Send to ERP",
                "endpoint": "https://api.example.com/invoices",
                "method": "POST",
                "headers": {"Authorization": "Bearer token"}
            },
            "action": {
                "id": "action-api",
                "name": "API Call",
                "description": "Make HTTP requests to external APIs"
            }
        }
    ],
    "edges": [
        {
            "id": "edge-1",
            "workflowId": "f73e9d7a-514f-48f3-a995-4f784c7e591b",
            "sourceNodeId": "node-1",
            "targetNodeId": "node-2"
        },
        {
            "id": "edge-2",
            "workflowId": "f73e9d7a-514f-48f3-a995-4f784c7e591b",
            "sourceNodeId": "node-2",
            "targetNodeId": "node-3"
        }
    ]
}
